// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

class PackedObjectPoolTest {

	@Test
	void repeatedIdentityAndEqualValuesShareOneCanonicalId() {
		PackedObjectPool pool = new PackedObjectPool(2);
		String retained = new String("planned.metric");

		int initial = pool.intern(retained);

		assertThat(pool.intern(retained)).isEqualTo(initial);
		assertThat(pool.intern(new String("planned.metric"))).isEqualTo(initial);
		assertThat(pool.size()).isOne();
		assertThat(pool.value(initial)).isSameAs(retained);
	}

	@Test
	void resetDiscardsCanonicalIdentityWithoutLeakingThePriorValue() {
		PackedObjectPool pool = new PackedObjectPool(1);
		String prior = new String("planned.metric");
		pool.intern(prior);

		pool.reset();
		String replacement = new String("planned.metric");
		int replacementId = pool.intern(replacement);

		assertThat(replacementId).isOne();
		assertThat(pool.size()).isOne();
		assertThat(pool.value(replacementId)).isSameAs(replacement);
	}
}
